/**
 * The Java assertClose: a relative tolerance floored at `rel` so values near
 * zero are not held to an impossible standard. The label identifies the
 * assertion, which the reported line number cannot.
 */
void assertClose(const char *what, double expected, double actual, double rel) {
    double tol = std::fmax(rel, std::abs(expected) * rel);
    if (!(std::abs(actual - expected) <= tol))
        ::redukti::test::reportFailure(
            __FILE__, __LINE__,
            std::string(what) + ": got " + doubleToString(actual) + " want " +
                doubleToString(expected) + " tol " + doubleToString(tol));
}

/**
 * Ends the test, the way a failed JUnit assertion ends the Java method. Only
 * the structural checks below use it: a wrong segment count means the indexing
 * that follows would run off the end of the vector.
 */
struct AbortTest {};

void assertCount(const char *what, std::size_t expected, std::size_t actual) {
    if (expected != actual) {
        ::redukti::test::reportFailure(
            __FILE__, __LINE__,
            std::string(what) + ": got " + std::to_string(actual) + " want " +
                std::to_string(expected));
        throw AbortTest();
    }
}

void assertHasValue(const char *what, bool present) {
    if (!present)
        ::redukti::test::reportFailure(__FILE__, __LINE__,
                                       std::string(what) + ": expected a value");
}

/** An absent aim_info reads as NaN so the assertion fails instead of the read. */
double aim_or_nan(const std::unique_ptr<specs::Field> &fld, std::size_t i) {
    if (!fld->aim_info.has_value())
        return NAN;
    return (*fld->aim_info)[i];
}

void accumulate(std::array<double, 5> &into, const std::array<double, 5> &add) {
    for (std::size_t i = 0; i < into.size(); i++)
        into[i] += add[i];
}


std::unique_ptr<optical::OpticalModel> build() {
    auto opm = std::make_unique<optical::OpticalModel>();
    auto sm = opm->seq_model.get();
    auto osp = opm->optical_spec.get();
    osp->pupil = std::make_unique<specs::PupilSpec>(
        osp, Pair<specs::ImageKey, specs::ValueKey>(specs::ImageKey::Image,
                                                    specs::ValueKey::Fnum),
        2.0);
    osp->fov = std::make_unique<specs::FieldSpec>(
        osp, Pair<specs::ImageKey, specs::ValueKey>(specs::ImageKey::Object,
                                                    specs::ValueKey::Angle),
        22.5, std::vector<double>{0.0, 0.707, 1.0}, true, false);
    osp->wvls = std::make_unique<specs::WvlSpec>(
        std::vector<specs::WvlWt>{specs::WvlWt(587.5618, 1.0)}, 0);
    opm->system_spec->title = "US 4,123,144 Example 8 (Leica Summicron R 50mm f/2)";
    opm->system_spec->dimensions = "mm";
    opm->radius_mode = true;
    sm->gaps[0]->thi = 1.0E10;
    {
        seq::SurfaceData sd(42.71, 3.99);
        sd.max_aperture(14.47)->rindex(1.7343, 28.19);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(195.38, 0.2);
        sd.max_aperture(13.53);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(20.5, 7.18);
        sd.max_aperture(12.01)->rindex(1.67133, 41.64);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(0.0, 1.29);
        sd.max_aperture(10.745)->rindex(1.7919, 25.55);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(14.94, 5.35);
        sd.max_aperture(9.195);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(0.0, 7.61);
        sd.max_aperture(9.0295);
        sm->add_surface(sd);
    }
    sm->set_stop();
    {
        seq::SurfaceData sd(-14.94, 1.0);
        sd.max_aperture(8.75)->rindex(1.65222, 33.6);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(0.0, 5.22);
        sd.max_aperture(9.635)->rindex(1.79227, 47.15);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(-20.5, 0.2);
        sd.max_aperture(10.19);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(0.0, 3.69);
        sd.max_aperture(11.48)->rindex(1.79227, 47.15);
        sm->add_surface(sd);
    }
    {
        seq::SurfaceData sd(-42.71, 37.32);
        sd.max_aperture(11.985);
        sm->add_surface(sd);
    }
    sm->do_apertures = false;
    opm->update_model();
    raytr::VigCalc::set_vig(opm.get(), false);
    opm->update_model();
    return opm;
}

